export type HealthCluesLocale = "en" | "vi";

export function healthCluesAdaptiveFocusLabel(locale: HealthCluesLocale, focusId: string) {
  const labels: Record<string, [string, string]> = {
    sleep: ["Sleep & Rest", "Giấc ngủ"], "weight-fitness": ["Weight & Fitness", "Cân nặng và thể lực"],
    "health-concern": ["Health Concerns", "Vấn đề sức khỏe"], "beauty-skin": ["Beauty & Skin", "Làm đẹp và làn da"],
    "healthy-aging": ["Healthy Aging", "Sống khỏe và duy trì sức trẻ"], stress: ["Stress & Wellbeing", "Căng thẳng và tinh thần"], other: ["Other", "Khác"],
  };
  const pair = labels[focusId];
  return pair ? pair[locale === "vi" ? 1 : 0] : null;
}

